WITH payload AS (SELECT $archive_payload$[{"id":"0ae1a757-fcf1-5adb-83cc-d082e530fb01","document_type":"judgment","category":"judicial","subcategory":"general","title":"-مخدرات -تعاطي احلشيش املخدر -حيازة سيجارة ملفوفة باحلشيش املخدر بقصد التعاطي -إقرار حتقيق ا -رجوع عن إقرار -وجود سوابق -التعزير بالسجن واملنع من السفر -إقامة حد","document_number":"3464492","case_number":"34113792","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/17","year":"1434","subject":"-مخدرات -تعاطي احلشيش املخدر -حيازة سيجارة ملفوفة باحلشيش املخدر بقصد التعاطي -إقرار حتقيق ا -رجوع عن إقرار -وجود سوابق -التعزير بالسجن واملنع من السفر -إقامة حد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3464492 :‬تاريخه‪1434/3/17 :‬هـ  ‬\n                     ‫رقم الدعوى‪34113792 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪  34180649‬تاريخه‪1434/4/7 :‬هـ‬\n\n\n‫‪ -‬مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬حيــازة ســيجارة ملفوفــة‬\n‫باحلشــيش املخــدر بقصــد التعاطــي ‪ -‬إقــرار حتقيقـ ًا ‪ -‬رجــوع عــن إقــرار‬\n‫‪ -‬وجــود ســوابق ‪ -‬التعزيــر بالســجن واملنــع مــن الســفر ‪ -‬إقامــة حــد‬\n                                                                     ‫املســكر ‪.‬‬\n\n\n\n\n‫‪ - 1‬قولــه تعالــى (يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n      ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون )‬\n‫‪ - 2‬املــواد ‪ 2/3‬و ‪ 1/41‬و ‪ 1/56‬و ‪ 60‬مــن نظــام مكافحــة املخــدرات‬\n                                                          ‫واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد ثالثــة مواطنــن بتعاطــي احلشــيش املخــدر وحيــازة‬\n‫احدهــم لســيجارة ملفوفــة باحلشــيش املخــدر بقصــد التعاطــي‪ ،‬وطلــب‬\n‫املدعــي العــام إثبــات مــا أســند إليهــم واحلكــم عليهم باملقتضى الشــرعي‬\n‫لقــاء تعاطيهــم حلشــيش املخــدر ومنعهــم مــن الســفر وبعقوبــة تعزيريــة‬\n‫وفــق الفقــرة ( ‪ ) 1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ‪ ،‬مت القبــض علــى املدعــى عليهــم بعــد العثــور‬\n‫بحوزتهــم علــى ســيجارة حتتــوي علــى احلشــيش املخــدر‪ ،‬إقــرار املدعــى‬\n\n                                                                                      ‫‪94‬‬\n\f     ‫عليهــم بتعاطــي احلشــيش املخــدر‪ ،‬إنــكار املدعــى عليــه املتهــم بحيــازة‬\n     ‫الســيجارة للحيــازة ووجــود إقــرار لــه حتقيق ـ ًا مبلــف الدعــوى بحيــازة‬\n     ‫الســيجارة امللفوفــة باحلشــيش بقصــد التعاطــي‪ ،‬ثبــوت إدانــة املدعــى‬\n     ‫عليهــم بتعاطــي احلشــيش املخــدر وثبــوت إدانــة املدعــى عليــة املتهــم‬\n     ‫باحليــازة بحيــازة الســيجارة امللفوفــة باحلشــيش بقصــد التعاطــي‪ ،‬إقامــة‬\n     ‫حــد املســكر علــى املدعــى عليهــم الثالثــة‪ ،‬تعزيــر املدعــى عليــه املــدان‬\n     ‫باحليــازة بالســجن واملنــع مــن الســفر‪ ،‬تصديــق احلكــم مــن محكمــة‬\n                                                                         ‫االســتئناف ‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n     ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n     ‫برقــم ‪ 34113792‬وتاريــخ ‪ 1434 / 3 / 9‬ه ـ املقيــدة باحملكمــة برقــم‬\n     ‫‪ 34532240‬وتاريــخ ‪ 1434 / 3 / 9‬ه ـ واملتعلقــة بدعــوى املدعــي العــام‬\n     ‫‪ ..... /‬ضــد كل مــن ‪ ...-1  :‬حامــل الســجل املدنــي رقــم (‪.......-2 ).......‬‬\n     ‫حامــل الســجل املدنــي رقــم (‪ ...... -3 ).....‬حامــل الســجل املدنــي رقــم‬\n     ‫(‪ )........‬ففــي يــوم  الثالثــاء ‪1434/ 3 / 17‬ه ـ فتحــت اجللســة الســاعة ‪45‬‬\n     ‫‪  9 :‬وفيهــا حضــر  املدعــي العــام واملدعــى عليهــم املدونــة هوياتهــم بعاليــه‬\n     ‫وقــدم املدعــي العــام الئحــة الدعــوى املتضمنــة مــا يلــي ‪ ( :‬أدعــي علــى‬\n     ‫كل مــن‪ ، ...........-1 :‬البالــغ مــن العمــر (‪ )24‬عامـ ًا ‪ ،‬ســعودي اجلنســية‬\n                                                                                   ‫ٍ‬\n     ‫مبوجــب الســجل املدنــي رقــم (‪ ، ).......‬غيــر محصــن‪ ،‬موظــف أهلــي ‪،‬‬\n     ‫املقبــوض عليــه بتاريــخ ‪1433/4/9‬ه ـ وأفــرج عنــه بتاريــخ ‪1433/4/9‬ه ـ‬\n     ‫اســتناد ًا للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬ويقيــم بحافظــة‬\n\n‫‪95‬‬\n\f‫القطيــف‪ ، ........-2 .‬البالــغ مــن العمــر (‪ )21‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ ، ).......‬غيــر محصــن‪ ،‬موظــف أهلــي ‪،‬‬\n‫املقبــوض عليــه بتاريــخ ‪1433/4/9‬ه ـ وأفــرج عنــه بتاريــخ ‪1433/4/9‬ه ـ‬\n‫اســتنا ًد للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬ويقيــم بحافظــة‬\n‫القطيــف‪ ، ..... -3 .‬البالــغ مــن العمــر (‪ )23‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ ، )......‬غيــر محصــن‪ ،‬موظــف أهلــي ‪،‬‬\n‫املقبــوض عليــه بتاريــخ ‪1433/4/9‬ه ـ وأفرج عنــه بتاريخ ‪1433/4/10‬هـ‬\n‫اســتنا ًد للمــادة (‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬ويقيــم بحافظــة‬\n‫القطيــف‪ .‬حيــث انــه بتاريــخ املوافــق ‪1432/4/9‬ه ـ قبــض علــى املدعــى‬\n‫عليهــم  و‪.....‬و‪(.....‬لــم يوجــه لهمــا تهمــة) مــن قبــل مركــز امــن املنشــآت‬\n‫بالســفانية وذلــك بعــد العثــور بحوزتهــم علــى ســيجارة ملفوفــة باحلشــيش‬\n‫املخــدر بلــغ وزنهــا (‪ )1‬جــرام واحــد بداخــل علبــة ســجائر مخبــأة باملقاعد‬\n‫اخللفيــة لبــاص الشــركة الــذي كانــوا يســتقلونه بالقــرب منهــم ‪ ،‬أثبــت‬\n‫التقريــر الكيمــاوي الشــرعي الصــادر مــن املركــز اإلقليمــي ملراقبــة‬\n‫الســموم باملنطقــة الشــرقية رقــم (‪ 1339‬ك ش)  بتاريــخ ‪1433/4/17‬ه ـ‬\n‫احتواءهــا علــى احلشــيش املخــدر ‪،‬وأثبــت تقريــري الســموم الشــرعية‬\n‫الصــادر مــن املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية‬\n‫رقــم (‪664‬م أ) ورقــم (‪663‬م أ) وتاريــخ ‪1433/4/17‬ه ـ ايجابيــة عينــة‬\n‫بــول املدعــى عليــه الثانــي والثالــث ملركبــات احلشــيش املخــدر إيجابيــة‬\n‫عينــة  بــول املدعــى عليــه الثانــي والثالــث ملركبــات احلشــيش املخــدر‬\n‫واســتهلكت العينــة املرســلة يف التحليــل وأقــر املدعى عليــه األول للفرقة‬\n‫القابضــة بــأن الســيجارة املضبوطــة تخصــه‪ .‬وباســتجواب املدعــى عليــه‬\n‫األول أقــر بتعاطــي احلشــيش املخــدر‪ .‬وباســتجواب املدعــى عليهــم الثانــي‬\n\n\n                                                                                     ‫‪96‬‬\n\f     ‫والثالــث اعترفــا بتعاطــي احلشــيش املخــدر‪ .‬وقــد أســفر التحقيــق عــن‬\n     ‫توجيــه االتهــام لهــم بتعاطــي احلشــيش املخــدر ولــأول بحيــازة ســيجارة‬\n     ‫ملفوفــة باحلشــيش املخــدر بلــغ وزنهــا (‪ )1‬جــرام واحــد بقصــد التعاطــي‪،‬‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة‪-1 :‬إقــرار األول املنــوه عنــه املرفــق باللفــه‬\n     ‫رقــم (‪ )5‬وســماع أقوالــه املنــوه عنهــا املدونــة علــى الصفحــة رقــم (‪ )2‬مــن‬\n     ‫دفتــر التحقيــق املرفــق باللفــه رقــم (‪-2 .)56‬إقــرار الثانــي والثالــث املنــوه‬\n     ‫عنهــا املدونــة علــى الصفحــة رقــم (‪ )5,7‬مــن دفتــر التحقيــق املرفــق باللفه‬\n     ‫رقــم (‪-3 .)56‬مــا ورد يف محضــر القبــض لفــه رقــم (‪-4 .)4‬التقاريــر‬\n     ‫الشــرعية املنــوه عنهــا املرفقــة لفــه رقــم (‪ .)24-22‬وبالبحــث عمــا إذا‬\n     ‫كان لهــم ســوابق لــم يعثــر لهــم علــي ســوابق مســجله‪ .‬وحيــث إن مــا‬\n     ‫أقــدم عليــه املذكــورون ‪-‬وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا ‪ -‬فعــل‬\n     ‫محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا لــذا أطلــب اآلتــي ‪ :‬أوالً‪ :‬احلكــم‬\n     ‫عليهــم باملقتضــى الشــرعي لتعاطيهــم احلشــيش املخــدر‪ .‬ثاني ـاً‪ :‬إثبــات‬\n     ‫مــا أســند إليهــم وفق ـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة‬\n     ‫املخــدرات‪ .‬واحلكــم عليهــم مبــا يلــي ‪-1 :‬بعقوبــة تعزيريــة الــواردة يف‬\n     ‫الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‪-2  .‬منعهــم‬\n     ‫مــن الســفر وفــق الفقــرة رقــم (‪ )1‬مــن املــادة (‪ )56‬مــن النظــام املشــار‬\n                                                            ‫إليــه‪ .‬وبــاهلل التوفيــق) ا‪ .‬ه ـ‬\n     ‫وبعــرض الدعــوى علــى املدعــى عليهــم أجــاب األول ‪ ....‬بقولــه مــا جــاء‬\n     ‫يف االتهــام املوجــه لــي غيــر صحيــح والصحيــح أنــه ال عالقــة لــي بقطعــة‬\n     ‫احلشــيش املضبوطــة وأمــا التعاطــي فقــد كنــت أتعاطــى احلشــيش‬\n     ‫وتركتــه قبــل القبــض علــي بفتــرة طويلــة تقــدر بثــاث ســنوات هــذا‬\n     ‫جوابــي ثــم أجــاب الثانــي ‪ ...‬بقولــه مــا جــاء يف االتهــام املوجــه لــي صحيــح‬\n\n\n‫‪97‬‬\n\f    ‫فقــد تعاطيــت احلشــيش املخــدر هــذا جوابــي ثــم أجــاب الثالــث ‪ ....‬بقولــه‬\n    ‫مــا جــاء يف االتهــام املوجــه لــي صحيــح فقــد تعاطيــت احلشــيش املخــدر‬\n    ‫هــذا جوابــي وبعــرض ذلــك علــى املدعــي العــام قــال الصحيــح مــا جــاء‬\n    ‫يف دعــواي وبســؤاله البينــة قــال بينتــي ذكرتهــا يف الدعــوى وأطلــب‬\n    ‫رصدهــا هــذا جوابــي وباالطــاع علــى أدلــة املدعــي العــام وجــدت علــى‬\n    ‫اللفــة رقــم ‪ 5‬إقــرارا منســوبا للمدعــى عليــه األول ‪ ...‬يتضمــن مــا نصــه‬\n    ‫‪ ( :‬أقــر أنــا املدعــو ‪ ......‬ســعودي اجلنســية ســجل مدنــي رقــم ‪ ......‬بــأن‬\n    ‫الســيجارة امللفوفــة تخصنــي وأحتمــل مســؤوليتها وعلــى ذلــك أوقــع ) ا‪.‬هـ‬\n    ‫كمــا وجــدت علــى اللفــة رقــم ‪ 22‬التقريــر الكيمــاوي رقــم ‪ 1339‬ك ش‬\n    ‫املتضمــن ‪ ( :‬إيجابيــة العينــة ملــادة احلشــيش املخــدر) ا‪.‬ه ـ وبعــرض األدلــة‬\n    ‫علــى املدعــى عليــه األول أجــاب بقولــه هــذا اإلقــرار وقعــت عليــه بســبب‬\n    ‫وعــد احملقــق لــي بإخراجــي مــن التوقيــف ومــا ورد فيــه غيــر صحيــح  هذا‬\n    ‫جوابــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء علــى إقــرار‬\n    ‫املدعــى عليهــم يف مجلــس القضــاء بتعاطــي احلشــيش وإقــرار املدعــى‬\n    ‫عليــه األول املرفــق باملعاملــة بعائديــة الســيجارة املضبوطــة لــه ولــم يدفــع‬\n    ‫إقــراره هــذا بدفــع معتبــر وبنــاء علــى التقريــر الكيمــاوي ولقولــه تعالــى‬\n    ‫‪( :‬يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس‬\n    ‫مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون ) وبنــاء علــى املــواد ‪3/2‬‬\n    ‫و‪ 41/1‬و‪ 56/1‬ولكــون املدعــى عليــه األول ليــس مــن أربــاب الســوابق‬\n    ‫ممــا يخولــه االســتفادة مــن املــادة ‪ 60‬مــن النظــام فقــد حكمــت مبــا‬\n    ‫يلــي ‪-1 :‬ثبــوت إدانــة املدعــى عليهــم بتعاطــي احلشــيش املخــدر وإدانــة‬\n    ‫األول ‪ ...‬بحيــازة ســيجارة ملفوفــة باحلشــيش املخــدر بلــغ وزنهــا (‪ )1‬جــرام‬\n‫واحــد بقصــد التعاطــي ‪ -2‬جلــد كل واحــد مــن املدعــى عليهــم ثمانـن    ‬\n\n\n                                                                                          ‫‪98‬‬\n\f     ‫جلــدة حــد املســكر أمــام مــأ مــن النــاس ‪ -3 .‬تعزيــر املدعــى عليــه األول‬\n     ‫بســجنه مــدة شــهر واحــد ومنعــه مــن الســفر بعــد خروجــه مــن الســجن‬\n     ‫مــدة ســنتني ‪ ،‬كمــا أفهمــت املدعــى عليهمــا الثانــي والثالــث بانطبــاق‬\n     ‫الفقــرة األولــى مــن املــادة ‪ 56‬عليهمــا وبعرض احلكــم على األطراف قرر‬\n     ‫املدعــي العــام عــدم قناعتــه ورغبتــه رفــع احلكــم حملكمــة االســتئناف‬\n     ‫بــدون الئحــة اعتراضيــة وقــرر املدعــى عليهــم قناعتهــم باحلكــم وبــاهلل‬\n          ‫التوفيــق وقــد مت االنتهــاء مــن حتريــره يف متــام الســاعة ‪،،، 10 : 25‬‬\n     ‫احلمد هلل وحده وبعد ففي يوم  االثنني ‪1434/ 4 / 22‬هـ  فتحت اجللسة‬\n     ‫الســاعة ‪  8 : 00‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب الفضيلــة‬\n     ‫قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم ‪ 34180649‬يف‬\n     ‫‪1434/4/7‬ه ـ املتضمــن املصادقــة علــى احلكــم  وبــاهلل التوفيــق وقــد مت‬\n                                  ‫االنتهــاء مــن حتريــره يف متــام الســاعة ‪،،،  8 : 15‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n     ‫املقيــدة لــدى احملكمــة برقــم ‪/.............‬ج‪ 2‬وتاريــخ ‪1434/3/23‬ه ـ‬\n     ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف‬\n     ‫برقــم ‪ 34/..........‬وتاريــخ ‪1434/3/17‬ه ـ املرفــق بهــا القــرار الصــادر‬\n     ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ...../‬املســجل برقــم ‪3464492‬‬\n     ‫وتاريــخ ‪1434/3/17‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد كلً مــن‬\n     ‫‪ ..../1‬و‪ ..../2‬و‪ ..../3‬يف قضيــة مخــدرات وقــد تضمــن القــرار حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n     ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪.‬واهلل املوفــق وصلــى اهلل‬\n             ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/4/7‬هــ‪.‬‬\n\n\n‫‪99‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":94,"source_page_end":99,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"874eafafc183bc2bfc2892cb9ba2aba8e762371c800ef9793c3d1fb4337d60e6","normalized_text_hash":"4eeb03c21ae0a1ae6e6a7999d3fc01f36e6319de2fac0bc0cdfa7a86481f06a0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p94-3464492"},{"id":"872700e0-684e-5606-b461-0e98e71277ec","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -حيازة احلبوب احملظورة بقصد التعاطي -إقرار -وجود سوابق -التعزير بالسجن واجللد واملنع","document_number":"34191754","case_number":"34173942","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/20","year":"1434","subject":"مخدرات -تعاطي مخدرات -حيازة احلبوب احملظورة بقصد التعاطي -إقرار -وجود سوابق -التعزير بالسجن واجللد واملنع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 34191754:‬تاريخه‪1434/4/20:‬هـ‬\n                    ‫رقم الدعوى‪34173942 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 34282925‬تاريخه‪1434/7/30 :‬هـ‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي مخــدرات‪ -‬حيــازة احلبــوب احملظــورة بقصــد‬\n‫التعاطــي‪ -‬إقــرار ‪ -‬وجــود ســوابق ‪ -‬التعزيــر بالســجن واجللــد واملنــع‬\n                                                              ‫مــن الســفر‪.‬‬\n\n\n\n\n                               ‫‪-1‬قولة تعالى ( ويحرم عليهم اخلبائث )‬\n           ‫‪-2‬املادة (‪ )41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n           ‫‪-3‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــي املدعــي العــام علــى املدعــى عليــه بحيــازة نصــف حبــة مــن حبــوب‬\n  ‫اإلمفيتامــن واســتعماله لهــا يف الســابق‪ ،‬حيــث قبــض علــى املدعــى‬\n‫عليــه بعــد مشــاهدة الفرقــة القابضــة لــه ابتالعــه كميــة مــن احلبــوب‪  ،‬‬\n  ‫وبتفتيــش الســيارة وجــد بالســيارة نصــف حبــة مــن اإلمفيتامــن وبتحليــل‬\n  ‫عينــة دم املدعــى عليــه تبــن احتوائهــا علــى مــادة اإلمفيتامــن وطلــب‬\n  ‫املدعــي العــام معاقبتــه لقــاء تعاطيــه احلبــوب احملظــورة ‪ ،‬كمــا طلــب‬\n  ‫ســجن املدعــى عليــه ومنعــه مــن الســفر بنــاء علــى املــواد (‪ )56/ 41‬مــن‬\n  ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪  ،‬صــادق املدعــى عليــه‬\n  ‫علــى دعــوى املدعــى العــام كمــا طلــب احلكــم بتعزيــر املدعــى عليــه‬\n\n                                                                                   ‫‪100‬‬\n\f      ‫باجللــد لقــاء اســتعماله احلبــوب احملظــورة بنــاء علــى مــا تقــدم حكمــت‬\n      ‫احملكمــة علــى املدعــى عليــه مبقتضــى املادتــن(‪ )56، 41‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات  العقليــة وهــو الســجن واملنــع مــن الســفر‬\n      ‫ـ ـ لــم يبــد املدعــي العــام اعتراض ـ ًا علــى احلكــم ‪ ،‬بينمــا قــرر املدعــى‬\n      ‫عليــه اعتراضــه علــى احلكــم بــدون الئحــة اعتراضيــة و ُصــدق احلكــم‬\n                                                          ‫مــن محكمــة اإلســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالطائــف برقــم ‪ ....‬وتاريــخ ‪ 1434/04/15‬هــ   املقيــدة‬\n      ‫باحملكمــة برقــم ‪ ...‬وتاريــخ ‪ 1434/04/15‬هــ   ففــي يــوم   الســبت‬\n      ‫املوافــق‪ 1434/04/20‬ه ـ افتتحــت اجللســة الســاعة ‪  10 : 00‬وفيهــا‬\n      ‫حضــر  املدعــي العــام ‪ .....‬بالتعميــد ‪ 1607‬يف ‪1433/10/18‬ه ـ وادعــى‬\n      ‫علــى احلاضــر باملجلــس الشــرعي ‪ ... /‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ....‬أنــه بتاريــخ ‪1434/3/4‬ه ـ وأثنــاء قيــام أفــراد مكافحــة‬\n      ‫املخــدرات بواجبهــم امليدانــي بحــي ‪ ..‬شــوهد املدعــى عليــه بقيــادة ســيارة‬\n      ‫رقــم اللوحــة ( ‪ )... ...‬ومتوقــف مبــكان منــزوي وعندمــا شــاهد أفــراد‬\n      ‫الفرقــة قــام بإبتــاع كميــة مــن احلبــوب وبالقبــض عليه وتفتيش الســيارة‬\n      ‫ضبــط بالــدرج األوســط بــن املقاعــد األماميــة نصــف حبــة أثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي رقــم ‪ 4243‬وتاريــخ ‪1434/3/9‬ه ـ احتوائهــا‬\n      ‫علــى مــادة االمفيتامــن احملظــورة وبتحليــل عينــة املدعــى عليــه أثبــت‬\n      ‫التقريــر الكيميائــي الطبــي الشــرعي رقــم ‪ 4243‬وتاريــخ ‪1434/3/9‬هـ‬\n\n‫‪101‬‬\n\f ‫احتوائهــا علــى اإلمفيتامــن وانتهــى التحقيــق إلــى اتهامــه بحيــازة نصــف‬\n ‫حبــه مــن حبــوب االمفيتامــن احملظــورة بقصــد التعاطــي واســتعماله لهــا‬\n ‫مــن الســابق وهــو فعــل محــرم شــرع ًا ومعاقــب عليــه نظامــا وبالبحــث‬\n ‫عــن ســوابقه عثــر لــه علــى أربــع ســوابق أحداهــا يف الترويــج واملخــدرات‬\n ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n ‫شــرع ًا فعــل محــرم شــرعا ومجــرم نظامــا أطلــب إثبــات مــا أســند إليــه‬\n ‫واحلكــم عليــه بالتالــي ‪ -1 :‬ســجنه بنــاء علــى الفقــرة األولــى مــن املــادة‬\n ‫الواحــدة واألربعــن مــن ذات النظــام ‪ -2 .‬منعــه مــن الســفر للخــارج‬\n ‫بعــد تنفيــذ محكوميتــه اســتنادا للمــادة السادســة واخلمســن مــن ذات‬\n ‫النظــام هــذه دعــواي ‪ .‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه‬\n ‫أجــاب مــا ذكــره املدعــي العــام يف دعــواه علــي صحيــح وباإلطــاع علــى‬\n ‫ســوابقه عثــر لــه علــى أربــع ســوابق إحداهــا يف الترويــج وبســؤاله عنهــا‬\n ‫صــادق عليهــا وباإلطــاع علــى التقريــر الكيميائــي الشــرعي رقم ‪4243‬‬\n ‫يف ‪1434/3/9‬ه ـ اثبــت احتــواء العينــة علــى مــادة االمفيتامــن احملظــورة‬\n ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة املتضمنــة اإلقــرار بالدعــوى‬\n ‫ولوجــود أربــع ســوابق مصــادق عليهــا إحداهــا يف الترويــج وإليجابيــة‬\n ‫التقريــر الكيميائــي ملــادة االمفيتامــن احملظــورة وألن ذلــك محــرم‬\n ‫شــرع ًا ألنــه مــن اخلبائــث ولقولــه تعالــى ( ويحــرم عليهــم اخلبائــث ) وبنــاء‬\n ‫علــى املــادة ‪ 41‬واملــادة ‪ 56‬مــن نظــام مكافحــة املخــدرات فقــد ثبــت لــدي‬\n‫إدانــة املدعــى عليــه مبــا نســب إليــه وحكمــت عليــه بســجنه ملــدة ســنتني ‬\n ‫تبــدأ مــن تاريــخ توقيفــه يف ‪1434/3/3‬ه ـ ومنعــه مــن الســفر للخــارج‬\n ‫بعــد تنفيــذ محكوميتــه ملــدة ســنتني وجلــده ســبعني جلــدة دفعــة واحــدة‬\n ‫وبعــرض احلكــم علــى املدعــى عليــه اعتــرض علــى احلكــم بالئحــة‬\n\n\n                                                                                         ‫‪102‬‬\n\f        ‫اعتراضيــة ولــم يبــد املدعــي العــام اعتــراض وأفهمــت املدعــى عليــه بــأن‬\n        ‫لــه مهلــة ثالثــن يومــا لتقــدمي الئحتــه بعدمــا جــرى تســليمه نســخة احلكم‬\n        ‫فــإن لــم يقــدم اعتراض ـ ًا فســترفع إلــى محكمــة االســتئناف بنــاء علــى‬\n        ‫املــادة ‪ 195 ، 194‬مــن نظــام اإلجــراءات اجلزائيــة وصلــى اهلل علــى نبينــا‬\n                      ‫محمــد حــرر يف ‪1434/4/20‬ه ـ الســاعة العاشــرة صباح ـ ًا ‪.‬‬\n        ‫احلمــد هلل وحــده وبعــد ويف هــذا اليــوم  األحــد املوافــق‪1434/08/07‬‬\n        ‫ه ـ افتتحــت اجللســة الســاعة الثانيــة عشــرة حيــث عــادت املعاملــة مــن‬\n        ‫محكمــة اإلســتئناف مصادقــا عليهــا بقــرار الدائــرة اجلزائيــة السادســة‬\n        ‫برقــم يف ‪1434/7/30‬ه ـ لــذا فقــد جــرى إثباتــه وبــاهلل التوفيــق ‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ ،‬حــرر يف  ‬\n                                                                 ‫‪ 1434/08/07‬هــ  ‪.‬‬\n                   ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n        ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n        ‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه‬\n        ‫احملكمــة بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بالطائــف‬\n        ‫رقــم(‪ )/‬وتاريخ(‪1434/7/17‬هـ)املرفــق بهــا القــرار رقــم(‪)/‬‬\n      ‫وتاريخ(‪1434/4/20‬هـ)الصــادر مــن فضيلــة الشــيخ‪ .... /‬القاضــي  ‬\n        ‫باحملكمــة اجلزائيــة بالطائــف ‪،‬املتضمــن دعــوى املدعــي العــام ضــد‪... /‬‬\n        ‫ســعودي اجلنســية ‪ ،‬املتهــم يف مخــدرات احملكــوم فيــه مبــادون باطنــه ‪،‬‬\n        ‫وبدراســة القــرار وصــورة ضبطــه والئحتــه اإلعتراضيــة تقــررت املوافقــة‬\n        ‫علــى احلكــم ‪ ،‬واهلل املوفق‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                       ‫وصحبــه وســلم‪.‬‬\n\n\n\n‫‪103‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":100,"source_page_end":103,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"835fb6c755e568dfa1f8f42ee82eb42afd36dbc6da4e5d13b1d2692b9e4ba8f7","normalized_text_hash":"989857712be89f491a47c08fd71f399fa35696ba161c09b92e25ac70b229fdef","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p100-34191754"},{"id":"164b7d17-98a8-5ee5-ad4e-c4a949f21b33","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -استعمال مخدرات -تعاطي احلشيش املخدر -شرب املسكر -قيادة السيارة حتت تأثير املسكر -التستر على مصدر املخدرات -إقرار -إقامة حد املسكر على متعاطي احلشيش - التعزير بالسجن واجللد واملنع من السفر -رد دعوى املدعي العام .","document_number":"34204114","case_number":"34177238","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/4","year":"1434","subject":"مخدرات -استعمال مخدرات -تعاطي احلشيش املخدر -شرب املسكر -قيادة السيارة حتت تأثير املسكر -التستر على مصدر املخدرات -إقرار -إقامة حد املسكر على متعاطي احلشيش - التعزير بالسجن واجللد واملنع من السفر -رد دعوى املدعي العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34204114  :‬تاريخه ‪1434/5/4:‬هـ  ‬\n                     ‫رقم الدعوى‪34177238 :‬‬\n       ‫رقم قرار التصديق من محكمة االستئناف‬\n             ‫‪ 34230254:‬تاريخه ‪1434/6/4:‬هـ‬\n\n\n\n‫مخــدرات ‪ -‬اســتعمال مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر‪ -‬شــرب‬\n‫املســكر ‪ -‬قيــادة الســيارة حتــت تأثيــر املســكر‪ -‬التســتر علــى مصــدر‬\n‫املخــدرات ‪ -‬إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطــي احلشــيش ‪-‬‬\n‫التعزيــر بالســجن واجللــد واملنــع مــن الســفر ‪ -‬رد دعــوى املدعــي العــام ‪.‬‬\n\n\n\n\n‫‪ -1‬ماذكــره أهــل العلــم مــن أنــه إذا اجتمــع حــدان مــن جنــس واحــد‬\n                               ‫ولــم يقامــا ‪ ،‬فإنــه يكتفــى بأحدهمــا‪.‬‬\n        ‫‪ -2‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه بحيــازة وتعاطــي احلشــيش‬\n‫املخــدر ‪ ،‬واملســكر ‪ ،‬والتســتر علــى مصــدر احلشــيش ‪ ،‬وطلــب إثبــات‬\n‫إدانتــه بقيــادة الســيارة حتــت تأثيــر املســكر ‪،‬حيــث طلــب املدعــي العــام‬\n‫معاقبتــه لقــاء شــرب املســكر ‪ ،‬وطلــب املدعــي العــام ســجن املدعــى‬\n‫عليــه ومنعــه مــن الســفر بنــاء علــى نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة وحيــث تقــدم أحــد األشــخاص ببــاغ يفيــد أن املدعــى عليــه‬\n‫وقــع يف حــادث مــروري واصطــدم بحلــه ‪ ،‬وأنــه يشــتبه أنــه يف  حالــة‬\n‫غيــر طبيعيــة ‪ ،‬وبســماع أقوالــه اعتــرف بتعاطــي املســكر واحلشــيش‬\n\n                                                                                   ‫‪104‬‬\n\f      ‫‪،‬أقــر املدعــى عليــه بتعاطيــه املســكر‪ ،‬واحلشــيش املخــدر كمــا‬\n      ‫أنكــر املدعــى عليــه حيازتــه للحشــيش املخــدر ‪  ،‬وتســتره علــى مصــدر‬\n      ‫ماضبــط معــه‪ُ ،‬ط ِلـ َـب مــن املدعــى العــام بينتــه علــى حيــازة املدعــى عليــه‬\n      ‫احلشــيش املخــدر‪ ،‬وعلــى التســتر ‪ ،‬وقــرر أنــه ليــس لديــه إال مــا أرفــق‬\n      ‫ضمــن طيــات املعاملــة ‪ ،‬حكمــت احملكمــة بإقامــة حــد املســكر لقــاء‬\n      ‫شــرب املســكر وتعاطــي احلشــيش واملنــع مــن الســفر وإثبــات اإلدانــة‬\n      ‫بقيــادة الســيارة حتــت تأثيــر املســكر وعقابــه عائــد لولــي األمــر وتعزيــر‬\n      ‫املدعــى عليــه لقــاء تعــدد ســوابقه‪ ،‬عــدم ثبــوت إدانــة املدعــى عليــه‬\n      ‫بالتســتر واحليــازة وبعــرض احلكــم علــى طــريف الدعــوى قــرر املدعــي‬\n      ‫وصــدق احلكــم مــن محكمــة االســتئناف  ‪.‬‬        ‫العــام االعتــراض بالئحــة ُ‬\n\n\n\n       ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n       ‫فلــدي أنــا (‪ ).........‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنــاء علــى‬\n       ‫املعاملــة الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n       ‫األحســاء برقــم ‪ 5603‬بتاريــخ ‪1434/4/16‬ه ـ واملقيــدة بهــذه احملكمــة‬\n       ‫برقــم ‪ 34946564‬وتاريــخ ‪1434/4/17‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n       ‫الرئيــس برقــم  ‪ 34177238‬وتاريــخ ‪1434/4/17‬ه ـ ففــي يــوم  االربعــاء‬\n       ‫املوافــق‪ 1434/05/1‬ه ـ افتتحــت اجللســة األولــى الســاعة ‪00:9‬وفيهــا‬\n       ‫حضــر املدعــي العــام ‪ ...‬املعمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب‬\n       ‫خطــاب ســعادة رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة‬\n      ‫األحســاء ذي الرقــم ‪ 13415‬والتاريــخ ‪1433/12/1‬ه ـ وقــرر دعواه قائال ‬\n       ‫بصفتــي مدعيـ ًا عامـ ًا بدائــرة اإلدعــاء العــام لدائــرة التحقيــق مبحافظــة‬\n\n‫‪105‬‬\n\f‫االحســاء أدعــي علــى اســم املتهــم‪ ... :‬اجلنــس‪ :‬ذكــر اجلنســية‪ :‬ســعودي‬\n‫الديانــة‪ :‬مســلم اللغــة‪  :‬العربيــة تاريــخ امليــاد‪ 1379/07/01 :‬مــكان‬\n‫امليــاد‪ :‬االحســاء العمــر‪55 :‬نــوع الهويــة‪ :‬الســجل املدنــي رقــم الهويــة‪... :‬‬\n‫تاريــخ اإلصــدار‪1408/07/18 :‬جهــة اإلصــدار‪ :‬أحــوال االحســاء املهنــة‪:‬‬\n‫موظــف حكومــي احلالــة اإلجتماعيــة‪ :‬متــزوج مــكان اإلقامــة‪ :‬األحســاء‬\n‫‪... /‬الشــارع‪  :‬رقــم املنــزل‪ :‬هاتــف املنــزل‪  :‬الهاتــف احملمــول‪ ... :‬جهــة‬\n‫اإليقــاف‪ :‬ســجن األحســاء تاريــخ القبــض‪ 1434/3/2 :‬حالــة املتهــم‪:‬‬\n                                                       ‫موقــوف تاريــخ اإلفــراج‪:‬‬\n‫اإلتهــام‪ :‬تعاطــي املؤثــرات العقليــة الســوابق‪:‬رقم احلكــم‪ 8497:‬تاريخــه‪:‬‬\n‫‪1423/04/19‬ه ـ مصــدره‪ :‬االحســاء اجلرميــة ‪ :‬قيــادة الســيارة وهــو بحالة‬\n‫ســكر ‪ -‬صــدم ‪ -‬شــرب املســكرات‪ .‬العقوبــة ‪80 :‬جلده‪+‬ســجن‪10‬أيام‬\n‫وســحب الرخصــة عــام ‪ +‬ســجن‪ 5‬أيــام ‪ +‬غرامــه ‪    150‬ريــال ‪+‬رقــم‬\n‫احلكــم‪ 129:‬تاريخــه‪1425/05/01 :‬ه ـ مصــدره‪ :‬االحســاء اجلرميــة‬\n‫‪ :‬قيــادة الســيارة وهــو بحالــة ســكر ‪ -‬هروبــه عــن نقطــة التفتيــش‪.‬‬\n‫العقوبة ‪ :‬ســجنه شــهرين ‪ 80 +‬جلده ‪ 50 +‬جلده ‪ 1400 +‬ريال ‪ +‬التعهد‬\n‫رقــم احلكــم‪ 33133095:‬تاريخــه‪1433/03/21 :‬ه ـ مصــدره‪ :‬االحســاء‬\n‫اجلرميــة ‪ :‬حيــازة املخــدرات ‪ -‬اشــتباه يف اســتعمال مخــدرات ‪ -‬تســتر علــى‬\n‫مــروج مخــدرات ‪ -‬شــرب املســكرات ‪ -‬حيــازة مســكر‪ .‬العقوبــة ‪80 :‬‬\n‫جلــده ‪ +‬ســجنه ‪7‬اشــهر ونصــف ‪ 60 +‬جلــده ‪ +‬منعــه مــن الســفر ســنتني‬\n‫باالطــاع علــى محضــر القبــض رقــم (‪ )22743‬ومحضــر ســماع‬\n‫األقــوال املعــد مــن قبــل شــرطة محافظــة األحســاء تبــن بأنــه بتاريــخ‬\n‫‪1433/12/6‬هــ   تقــدم ‪ ، ... /‬ســعودي اجلنســية ‪ ،‬مبوجــب الهويــة‬\n‫الوطنيــة رقــم (‪  )...‬ببــاغ مفــاده بــأن املدعــى عليــه وقــع لــه حــادث مــروري‬\n\n\n                                                                                        ‫‪106‬‬\n\f          ‫واصتــدم مبحــل احلالقــة العائــد لــه ويشــتبه بأنــه يف حالــة غيــر طبيعيــة ‪.‬‬\n          ‫وبســماع أقــوال ابــن املدعــى عليــه ‪ ....‬أفــاد بــأن ســبب عــدم حضــور والــده‬\n          ‫إلــى مركــز الشــرطة كونــه يف حالــة ســكر وقــد نتــج عن ذلــك تعرضه‬\n                              ‫حلــادث مــروري واصتدامــه مبحــل احلالقــة العائــد للمبلغ ‪.‬‬\n          ‫وباســتجواب املدعــى عليــه أقــر بتعاطــي احلشــيش املخــدر وشــرب‬\n                                        ‫املســكر وقيــادة الســيارة حتــت تأثيرهمــا ‪.‬‬\n          ‫وقــد أثبــت تقريــر الســموم الشــرعية رقــم (‪1666‬م أ) إيجابيــة عينــة‬\n              ‫الســوائل املأخــوذة مــن املدعــى عليــه ملركبــات احلشــيش املخــدر‪.‬‬\n          ‫وانتهــى التحقيــق إلــى توجيــه االتهــام لــه بشــرب املســكر وتعاطــي‬\n          ‫احلشــيش املخــدر والتســتر علــى مصدرهــا وقيــادة الســيارة حتــت‬\n          ‫تأثيرهمــا ‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف إقــراره‬\n          ‫املدونــة علــى الصفحــة رقــم ( ‪ )2/1‬مــن دفتــر االســتجواب املرفــق علــى‬\n          ‫اللفــة رقــم (  ‪ -2)  30‬مــا جــاء يف أقــوال ابــن املدعــى عليــه املدونــة علــى‬\n          ‫الصفحــة رقــم (‪ )12‬مــن ملــف إجــراءات االســتدالل االوليــة املرفــق علــى‬\n      ‫اللفــة رقــم (‪ -3)2‬تقريــر الســموم الشــرعية املرفــق علــى اللفــة رقــم ( ‪    )12‬‬\n          ‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n          ‫فعــل محــرم ومجــرم ومعاقــب عليــه نظام ـ ًا يف ضــوء الفقــرة الثانيــة مــن‬\n          ‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n          ‫باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ؛ لــذا‬\n          ‫أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪ /1-:‬حــد املســكر‬\n          ‫‪/2.‬العقوبة الواردة يف الفقرة األولى من املادة (‪ )41‬من نظام مكافحة‬\n          ‫املخــدرات واملؤثــرات العقليــة لتعاطيــه احلشــيش املخــدر ‪ /3.‬منعــه مــن‬\n          ‫الســفر خــارج البــاد وفق ـ ًا للفقــرة األولــى مــن املــادة (‪ )56‬مــن النظــام‬\n\n\n‫‪107‬‬\n\f‫املشــار إليــه‪ /4.‬إثبــات إدانتــه بقيــادة الســيارة حتــت تأثيــر املســكر‬\n‫وتعاطــي احلشــيش املخــدر وفقـ ًا للفقــرة رقــم (‪ )8‬مــن اجلــدول رقــم (‪، )1‬‬\n‫امللحــق بنظــام املــرور ‪ ،‬الصــادر باملرســوم امللكــي رقــم (م‪ )85/‬وتاريــخ‬\n‫‪1428/10/26‬هـ ـ وإفهامــه بــأن عقوبتــه الــواردة بالفقــرة رقــم (‪ )1‬مــن‬\n‫املــادة رقــم (‪ )68‬و املــادة رقــم (‪ ، )76‬مــن النظــام املشــار إليــه آنف ـ ًا ‪،‬‬\n‫تقررهــا اجلهــة املختصــة وفقـ ًا للفقــرة رقــم (‪ )2‬مــن قــرار مجلــس الــوزراء‬\n‫رقــم (‪ )315‬يف ‪1428/10/24‬هــ‪ /5‬عقوبــة تعزيزيــة لتســتره على مصدر‬\n‫املخــدرات ‪ ،‬والتشــديد عليــه لكثــرة ســوابقه اســتناداً  لتعميــم صاحــب‬\n‫الســمو امللكــي وزيــر الداخليــة رقــم (‪2/8346/4/5/1‬س) وتاريــخ‬\n‫‪1432/2/8‬ه ـ ‪ .‬وبــاهلل التوفيــق هكــذا ا َّدعــى ؛ عليــه فقــد حضــر‬\n‫املدعــى عليــه وبعــد التأكــد مــن هويتــه جــرى عــرض دعــوى املدعــي‬\n‫العــام عليــه فأجــاب قائ ـاً‪ :‬صحيــح مــا نســبه لــي املدعــي العــام مــن‬\n‫واقعــة القبــض ومــن شــربي للمســكر واســتعمالي  للحشــيش املخــدر‬\n‫وصحيــح اعتــرايف ونســبة الســوابق الثــاث لــي وقد أخــذت محكوميتها‬\n‫وصحيــح أيضـ ًا قيادتــي للســيارة حتــت تأثيــر املســكر وحتــت اســتعمال‬\n‫احلشــيش  ولكــن لــم يكــن بحوزتــي أي ممنوعــات حــال القبــض علــي‬\n‫وغيــر صحيــح تســتري علــى مصــدر املخــدرات هكــذا أجــاب ثــم جــرى‬\n‫ســؤال املدعــي العــام هــل لديــه بينــة علــى مانفــاه املدعــى عليــه فقــال ‪:‬‬\n‫ـدي ســوى مــا يف أوراق املعاملــة هكــذا أجــاب ثــم جــرى االطــاع‬    ‫ليــس لـ َّ‬\n‫علــى جميــع أوراق املعاملــة ومنهــا ‪:‬تقريــر ســموم الشــرعية الصــادر‬\n‫مــن قســم الكيميــاء الشــرعية باملركــز اإلقليمــي ملراقبــة الســموم‬\n‫التابــع للمديريــة العامــة للشــؤون الصحيــة باملنطقــة الشــرقية برقــم (‬\n‫‪ 1666‬م أ ) لعــام  ‪1433‬ه ـ املتضمــن إيجابيــة عينــة الســوائل املأخــوذة‬\n\n\n                                                                                       ‫‪108‬‬\n\f        ‫مــن املدعــى عليــه ملركبــات احلشــيش املخــدر كمــا  جــرى االطــاع‬\n      ‫علــى كــرت ســوابق املدعــى عليــه املتضمــن وجــود ثــاث ســوابق عليــه  ‬\n        ‫كمــا جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه املتضمنــة‬\n        ‫أنــه أوقــف بتاريخ‪1434/03/02‬ه ـ فبنــاء علــى مــا ورد مــن الدعــوى‬\n        ‫واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد مــن أهليتــه  وملــا‬\n        ‫ورد يف محضــر القبــض واعتــراف املدعــي عليــه ومبــا أنــه  أقـ َّـر بشــرب‬\n        ‫املســكر وحــد املســكر أن يجلــد صاحبــه ثمانــون جلــدة دفعــة واحــدة‬\n        ‫علنـ ًا كمــا اســتقر عليــه عمــل األمــة ومبــا أ َّنــه أقـ َّـر باســتعمال احلشــيش‬\n      ‫املخــدر واســتعماله يأخــذ حكــم املســكر للتوافــق بينهمــا يف منــاط  ‬\n        ‫احلكــم وملــا قــرره أهــل العلــم أنــه إذا اجتمــع حــدان مــن جنــس واحــد‬\n        ‫ولــم يقامــا فإ َّنــه يكتفــى بأحدهمــا ممــا يســتوجب إقامــة حـ ِّـد واحــد‬\n        ‫علــى املدعــى عليــه  كمــا يتوجــه اســتحقاقه للعقوبــة الــواردة يف املــادة‬\n        ‫السادســة واخلمســن مــن نظــام مكافحــة املخــدرات الفقــرة األولــى‬\n        ‫منهــا رمبــا أ َّنــه أقــر بقيــادة الســيارة حتــت تأثيــر املســكر وحتــت تأثيــر‬\n        ‫اســتعمال احلشــيش املخــدر وإثبــات إدانتــه بذلــك لــدى هــذه احملكمــة‬\n        ‫والعقوبــة لــدى ولــي األمــر حســب األنظمــة املرعيــة التــي ال تتعــارض مــع‬\n        ‫أن املدعــى عليــه أنكــر دعــوى املدعــي العــام‬        ‫املصالــح الشــرعية ومبــا َّ‬\n        ‫باتهامــه بالتســتر علــى مصــدر املخــدرات والبينــة للمدعــي العــام علــى‬\n        ‫ذلــك ممــا يســتوجب ر َّد دعــوى املدعــي العــام بإثبــات إدانتــه بذلــك ومبــا‬\n        ‫أن  للمدعــى عليــه ســوابق أخــذ محكوميتيهــا ثــم عــاود لفعــل املعصيــة‬\n        ‫ممــا  يتوجــه تعزيــزه لــذا كلــه وألجــل احلــق العــام حكمــت علــى املدعــى‬\n        ‫ـدي إدانــة املدعــى عليــه بشــرب املســكر‬        ‫عليــه باآلتــي ‪ :‬أو ًال ‪ /‬ثبــت لـ َّ‬\n        ‫واســتعمال احلشــيش املخــدر ويجلــد حــد املســكر ثمانــن جلــدة دفعــة‬\n\n\n‫‪109‬‬\n\f  ‫واحــدة علن ـ ًا ثاني ـ ًا ‪ /‬وأن مينــع مــن  الســفر مــدة عامــن حســب مقتضــى‬\n  ‫مــا ورد يف املــادة السادســة واخلمســن مــن النظــام نفســه علــى أن يكــون‬\n  ‫ـدي إدانــة املدعــى‬‫املنــع ابتــداء مــن انتهــاء محكوميتــه ثالثـاً‪ /‬لــم يثبــت لـ َّ‬\n  ‫عليــه بحيــازة أي ممنوعــات وقــررت ر َّد دعــوى املدعــي العــام مبعاقبــة‬\n  ‫املدعــى عليــه بالعقوبــة الــواردة يف املــادة الواحــدة واألربعــن مــن نظــام‬\n  ‫ـدي إدانــة املدعــى عليــه بالتســتر‬ ‫مكافحــة املخــدرات رابعـ ًا ‪ /‬لــم يثبــت لـ َّ‬\n  ‫علــى مصــدر املخــدر وقــررت ر َّد دعــوى املدعــي العــام بإثبــات إدانتــه‬\n  ‫ـدي إدانتــه بقيــادة الســيارة حتــت تأثيــر املســكر‬      ‫بذلــك ‪.‬خامسـ ًا ‪ /‬ثبــت لـ َّ‬\n  ‫أن عقوبتــه عائــدة لــوي األمــر  ‪.‬‬    ‫وحتــت تأثيــر احلشــيش املخــدر وأفهمتــه َّ‬\n  ‫سادس ـ ًا ‪ /‬وأن يعــزر عــن عــدم ارتداعــه مــن عقوبــات الســوابق املاضيــة‬\n  ‫بســجنه ملــدة ســتة أشــهر مــن تاريــخ إيقافــه علــى ذمــة القضيــة وبجلــده‬\n  ‫مائــة وعشــرون جلــدة مفرقــة علــى ثــاث دفعــات كل دفعــة أربعــون‬\n  ‫جلــدة وبــن كل دفعــة وأخــرى مــدة التقــل عــن عشــرة أيــام وبــن جلــد‬\n‫احلــد والتعزيــر مــدة التقــل عــن عشــرة أيــام ويكــون جلــد احلــد هــو املقــدم  ‬\n  ‫وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليــه بحقــه يف التمييــز‬\n  ‫قــرر قناعتــه باحلكــم  وطلــب املدعــي العــام  رفــع احلكــم للتمييــز وأن‬\n  ‫الئحتــه االعتراضيــة هــي الئحــة الدعــوى هــذا وجــرى توجيــه املدعــى‬\n  ‫عليــه  مبــا يلــزم ومــن ذلــك حرمــة اســتعمال  احلشــيش املخــدر  وأثــره‬\n  ‫الســيئ علــى العقــل واملــال وأقفلــت اجللســة التاســعة والنصــف وصلــى اهلل‬\n  ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن  حــرر احلكــم يف‬\n                                                                       ‫‪1434/05/01‬ه ـ ‪.‬‬\n  ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n  ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n\n\n                                                                                               ‫‪110‬‬\n\f      ‫لــدى احملكمــة برقــم ‪/341250754‬ج‪ 2‬وتاريــخ ‪1434/5/22‬ه ـ الواردة‬\n      ‫مــن فضيلــة القائــم بعمــل رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n      ‫برقــم ‪ 34946564‬وتاريــخ ‪1434/5/19‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ .../‬املســجل برقــم ‪34204114‬‬\n      ‫وتاريــخ ‪1434/05/04‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ .../‬يف‬\n      ‫قضيــة مخــدرات وســكر وتســتر وقــد تضمــن القــرار حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                     ‫نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/6/4‬هــ‪.‬‬\n\n\n\n\n‫‪111‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":104,"source_page_end":111,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"12d86f8b2a3a2738ab89962a12db1e5977f6edd84d81f273139cb2d8a9052560","normalized_text_hash":"75b87a77fb51f216b9eafa11eb85f5a8487b88e72be972eb53606dde9df5d8ac","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p104-34204114"},{"id":"50e8825b-b300-52a3-aec3-e45065585cb2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -انبعاث رائحة املسكر من أنفاس املدعى عليه -تعاطي احلبوب احملظورة -شرب املسكر -إقرار -حد املسكر التعزير باملنع من السفر .","document_number":"34259189","case_number":"34177798","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/4","year":"1434","subject":"مخدرات -تعاطي مخدرات -انبعاث رائحة املسكر من أنفاس املدعى عليه -تعاطي احلبوب احملظورة -شرب املسكر -إقرار -حد املسكر التعزير باملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪  34259189 :‬تاريخه ‪1434/7/4:‬هـ  ‬\n                     ‫رقم الدعوى‪34177798 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n  ‫تاريخه‪1434/10/20 :‬هـ‬          ‫‪34334667‬‬\n\n\n\n‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬انبعــاث رائحــة املســكر مــن أنفــاس‬\n‫املدعــى عليــه‪ -‬تعاطــي احلبــوب احملظــورة‪ -‬شــرب املســكر‪ -‬إقــرار ‪ -‬حــد‬\n                                   ‫املســكر ـ التعزيــر باملنــع مــن الســفر ‪.‬‬\n\n\n\n\n                                         ‫‪.1‬قاعدة (املرء مؤاخذ بإقراره ) ‪.‬‬\n‫‪.2‬قولــه صلــى اهلل عليــه وســلم فيمــا أخرجــه اإلمــام أحمــد وأبــو داود‬\n                            ‫والنســائي ‪ ( :‬مــن شــرب اخلمــر فاجلــدوه) ‪.‬‬\n‫‪.3‬عمــل الصحابــة ‪ ،‬وإجمــاع األمــة ‪ ،‬علــى جلــد شــارب املســكر ثمانــن‬\n                                                                      ‫جلــدة ‪.‬‬\n            ‫‪.4‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n‫‪.5‬املــادة (‪ )30‬مــن الالئحــة التنفيذيــة مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة ‪ ،‬والتــي جعلــت للقاضــي الســلطة التقديريــة‬\n                                                        ‫لســجن املتعاطــي‪.‬‬\n‫‪.6‬مــا ذكــره أهــل العلــم مــن أن (العقوبــة التعزيريــة تدخــل يف العقوبــة‬\n                                                                   ‫احلديــة )‪.‬‬\n\n\n\n\n                                                                                  ‫‪112‬‬\n\f      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــربه للمســكر‪ ،‬وتعاطــي‬\n      ‫احلبــوب احملظــورة حيــث أنــه أثنــاء عمــل هيئــة األمــر باملعــروف والنهــي‬\n      ‫عــن املنكــر  بعملهــا املعتــاد  شــوهد املدعــى عليــه يف ســيارته يف مــكان‬\n      ‫منــزوي وكان صــوت املوســيقى الصاخبــة فتــم التوجــه إليــه للتأكــد‬\n      ‫مــن وضعــه وعنــد مشــاهدته للفرقــة بانــت عليــه عالمــات اإلرتبــاك‬\n      ‫وبالتحــدث معــه تبــن أنــه يف حالــة ســكر‪ ،‬فتــم إحالتــه للجهــة األمنيــة‪،‬‬\n      ‫طلــب املدعــى العــام إقامــة احلــد عليــه وتعزيــره بالســجن‪ ،‬واملنــع مــن‬\n      ‫الســفر‪،‬طبق ًا للمادتــن (‪ ) 56,41‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة‪  ،‬أقــر املدعــى عليــه بشــربه للمســكر‪ ،‬وبتعاطــي‬\n      ‫احلبــوب احملظــورة‪ ،‬حكــم علــى املدعــى عليــه بجلــده حــد املســكر ‪،‬‬\n      ‫بنــاء علــى مــا تقــدم حكمــت احملكمــة علــى املدعــى عليــه مبنعــه مــن‬\n      ‫الســفر طبق ـ ًا للمــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليةوصــرف القاضــي النظــر عــن طلــب املدعــى العــام تطبيــق املــادة‬\n        ‫(‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة بحــق املدعــى‬\n      ‫عليــه ‪ ،‬وقــرر املدعــى العــام اعتراضــه علــى احلكــم بــدون الئحــة ‪  ،‬‬\n        ‫وقنــع املدعــى عليــه مبــا صــدر بحقــه مــن حكــم ‪ ،‬وصــدق احلكــم مــن‬\n                                                            ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪113‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/7/4‬ه ـ لــدي أنــا‬\n‫ـاء علــى املعاملــة احملالــة‬\n                           ‫‪ ....‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n‫إلينــا مــن رئيــس احملكمــة برقــم () وتاريــخ ‪1434/4/17‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر ‪ ....‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‬\n‫(‪ )...‬وقــدم املدعــي العــام ‪ ...‬الئحــة اإلدعــاء املتضمنــة بصفتــي مدعي ـ ًا‬\n‫عام ـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية أدعــي‬\n‫علــى املذكــور أعــاه فإنــه باالطــاع علــى محضــر القبــض املعــد مــن‬\n‫قبــل هيئــة األمــر باملعــروف والنهــي عــن املنكــر باخلبــر تبــن أنــه يف‬\n‫يــوم الثالثــاء املوافــق ‪1433/7/1‬هــ  وأثنــاء دوريتهــم املعتــادة  شــوهد‬\n‫املذكــور داخــل ســيارته مــن نــوع (‪ )........‬يف مــكان منــزوي وكان‬\n‫يصــدر مــن الســيارة أصــوات املوســيقى بشــكل صاخــب  فتــم التوجــه‬\n‫إليــه للتأكــد مــن وضعــه وعنــد مالحظتــه للفرقــة بــدأ عليــه عالمــات‬\n‫االرتبــاك واخلــوف وبالتحــدث معــه تبــن إنــه بحالــة ســكر وباستشــمامه‬\n‫تبــن انبعــاث رائحــة املســكر مــن أنفاســه وتعثــر ســماع أقوالــه كونه يف‬\n‫حالــه ســكر و مت إحالتــه إلــى شــرطة العزيزيــة و ســحب عينــة دم وعينــة‬\n‫بــول للمدعــى عليــه ومت إطــاق ســراحه مــن قبــل اجلهــة املختصــة  وصــدر‬\n‫بحقــه  تقريــر املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية‬\n‫رقــم (‪1470‬م  أ) وتاريــخ ‪1433/7/7‬ه ـ ســلبية العينتــن املرســلة للمــواد‬\n‫الكحوليــة  وايجابيــة العينتــن ملركــب اإلمفيتامــن املنبهــة واملدرجــة‬\n‫باجلــدول الثانــي فئــة (ب) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة ومت إعــادة إيقافــه بشــعبة مكافحــة املخــدرات بالدمــام بتاريــخ‬\n\n                                                                                     ‫‪114‬‬\n\f      ‫‪1434/2/9‬ه ـ ومت  اإلفــراج عنــه بعــد ذلــك بتاريــخ  ‪1434/02/18‬ه ـ‬\n      ‫وباســتجوابه أنكــر شــربه للمســكر كمــا أنكــر تعاطيــه املؤثــرات‬\n      ‫العقليــة وقــد انتهــى التحقيــق معــه إلــى اتهامــه  بتعاطي احلبــوب احملظورة‬\n          ‫( االمفيتامــن )  وشــرب املســكر وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n      ‫‪ -1‬مــا ورد مبحضــر القبــض والتفتيــش املشــار لــه املرفــق بــاألوراق لفــه‬\n                                                                                 ‫رقــم ( ‪) 2‬‬\n                    ‫‪ -2‬التقرير الكيميائي الشرعي املرفق على اللفة رقم (‪)14‬‬\n                                   ‫‪ -3‬محضر االستشمام املرفق على اللفة رقم (‪)4‬‬\n      ‫‪ -4‬محضــر تعــذر االســتجواب لكــون املدعــى عليــه بحالــة ســكر‬\n      ‫املرفــق علــى اللفــة رقــم (‪ )1‬واملــدون علــى الصفحــة (‪ )6‬وحيــث أن مــا‬\n      ‫أقــدم عليــه املدعــى عليــه  وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرعا ونظامــا اطلــب إثبــات إدانتــه مبــا هــو‬\n      ‫منســوب إليــه واحلكــم عليــه وفــق الفقــرة الثانيــة مــن املــادة الثالثــة مــن‬\n                            ‫نظــام مكافحــة املخــدرات واحلكــم عليــه مبــا يلــي‪:‬‬\n      ‫‪ -1‬بعقوبــة الســجن وفــق الفقــرة (‪)1‬مــن املــادة (‪)41‬مــن النظــام مــع‬\n                                                        ‫مراعــاة املــادة ‪ 30‬مــن الالئحــة‬\n                ‫‪2‬ـ منعة من السفر وفق الفقرة رقم (‪ )1‬من املادة(‪)56‬من النظام‬\n      ‫ثانيــا ‪ -‬احلكــم عليــه بحــد الســكر لقــاء شــربه للمســكر وبــاهلل‬\n      ‫التوفيــق وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام‬\n      ‫صحيــح جملــة وتفصيــا فقــد شــربت املســكر وتعاطيــت احلبــوب‬\n      ‫احملظــورة وأنــا تائــب ونــادم هــذه إجابتــي وبعــد تدويــن مــا ســبق جــرى‬\n      ‫االطــاع علــى صحيفــة الســوابق املرفقــة باملعاملــة واملتضمنــة عــدم‬\n      ‫وجــود ســوابق مســجلة علــى املدعــى عليــه فبنــاء علــى مــا تقــدم مــن‬\n\n\n‫‪115‬‬\n\f‫الدعــوى واإلجابــة املتضمنــة املصادقــة وحيــث إن املــرء مؤاخــذ بإقــراره‬\n‫ولقولــه صلــى اهلل عليــه وســلم»من شــرب اخلمــر فاجلدوه»أخرجــه أحمــد‬\n‫وأبــو داود والنســائي وألن عمر‪-‬رضــي اهلل عنه‪-‬جلــد يف حــد اخلمــر‬\n‫ثمانــن جلــدة وكان ذلــك مبحضــر مــن املهاجريــن واألنصار‪-‬رضــي اهلل‬\n‫عنهم‪-‬فلــم ينكــره أحــد منهــم واســتناد ًا للمــادة الثالثــة واملــادة السادســة‬\n‫واخلمســن مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وحيــث إنــه‬\n‫ال جرميــة وال عقوبــة إال بنــص وحيــث إن العقوبــة الــواردة يف املــادة احلاديــة‬\n‫واألربعــن مــن نظــام مكافحــة املخــدرات ال تنطبــق علــى التعاطــي‬\n‫واالســتعمال بينمــا العقوبــة الــواردة يف املــادة السادســة واخلمســن مــن‬\n‫النظــام تنطبــق عليــه وحيــث إنــه ال توجــد ســوابق مســجلة علــى املدعــى‬\n                                                                               ‫عليــه‬\n‫وحيــث إن املــادة الثالثــن مــن الالئحــة التنفيذيــة لنظــام مكافحــة‬\n‫املخــدرات جعلــت ســجن املتعاطــي للمــواد املخــدرة ســلطة تقديريــة‬\n‫للقاضــي وحيــث إن العقوبــة علــى تعاطــي احلبــوب احملظــورة تعزيريــة لــذا‬\n‫فإنهــا تدخــل يف العقوبــة احلديــة وعليــه فقــد ثبــت لــدي إدانــة املدعــى‬\n‫عليــه بشــرب املســكر وتعاطــي احلبــوب احملظــورة وحكمــت عليــه لقــاء‬\n‫ذلــك مبــا يلــي ‪/1‬جلــده حــد املســكر ثمانــن جلــدة ‪/2‬منعــة مــن الســفر‬\n‫خــارج اململكــة مــدة ســنتني تبــدأ مــن حــن اكتســاب احلكــم القطعيــة‬\n‫‪/3‬صرفــت النظــر عــن طلــب املدعــي العــام إيقــاع العقوبــة الــواردة يف‬\n‫املــادة احلاديــة واألربعــن مــن نظــام مكافحــة املخــدرات علــى املدعــى‬\n‫عليــه  وبعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه بــه وقــرر املدعــي‬\n‫العــام االعتــراض بالئحــة فأجيــب لطلبــه ومت تســليمه نســخة مــن احلكــم‬\n‫وأفهــم بتقــدمي االعتــراض عليــه خــال مهلــة ثالثــن يومــا وأنــه إذا انتهــت‬\n\n\n                                                                                        ‫‪116‬‬\n\f      ‫هــذه املهلــة ولــم يتقــدم باعتراضــه ســقط حقــه يف ذلــك وســوف يتــم‬\n      ‫رفــع احلكــم إلــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة وبــاهلل‬\n           ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وبــه حــرر يف ‪1434/7/4‬هــ‪.‬‬\n      ‫ويف يــوم األربعــاء املوافــق ‪1434/11/19‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫العاشــرةوخمس وعشــرين دقيقــة وقــد عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف برقــم () وتاريــخ ‪1434/11/11‬هــ  املتعلقــة بدعــوى املدعــي‬\n      ‫العــام ضــد ‪ ..../‬وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة‬\n      ‫برقــم () وتاريــخ ‪1434/10/20‬ه ـ املتضمــن املصادقــة علــى احلكــم لــذا‬\n      ‫جــرى إحلــاق ذلــك حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                                                  ‫محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم وتاريــخ ‪1434/9/10‬ه ـ الــواردة مــن فضيلــة رئيس‬\n      ‫احملكمــة اجلزائيــة مبدينــة الدمــام برقــم  وتاريــخ ‪1434/8/28‬هـ املرفق‬\n      ‫بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمة الشــيخ‪ ... /‬املســجل‬\n      ‫برقــم وتاريــخ ‪1434/7/4‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪.../‬‬\n      ‫يف قضيــة خمــور وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n      ‫املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                          ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/10/20‬هــ‪.‬‬\n\n\n\n\n‫‪117‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":112,"source_page_end":117,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"79692dcb1485dce94b873e3af040489834b85b8d1ba465486bca2bc501b0892c","normalized_text_hash":"88f3e9a40794ac2374f272d962fa1df243abd76b13f0b602ab92729b12c4f44c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p112-34259189"},{"id":"d81c766e-2378-565f-9bd1-5b9ae64b4dbe","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -استعمال مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب املنبهة احملظورة -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير باجللد واملنع من السفر.","document_number":"34221686","case_number":"34210269","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/25","year":"1434","subject":"مخدرات -استعمال مخدرات -تعاطي احلشيش املخدر -تعاطي احلبوب املنبهة احملظورة -إقرار -إقامة حد املسكر على متعاطي احلشيش -التعزير باجللد واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34221686 :‬تاريخه‪1434/5/25 :‬هـ‬\n                   ‫رقم الدعوى‪34210269 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n        ‫‪    342362903‬تاريخه ‪1434/6/11 :‬هـ‬\n\n\n\n‫مخــدرات ‪ -‬اســتعمال مخــدرات ‪ -‬تعاطــي احلشــيش املخــدر‪ -‬تعاطــي‬\n‫احلبــوب املنبهــة احملظــورة‪ -‬إقــرار ‪ -‬إقامــة حــد املســكر علــى متعاطــي‬\n                    ‫احلشــيش ‪ -‬التعزيــر باجللــد واملنــع مــن الســفر‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه تعلى(يــا أيهــا الذيــن آمنــوا إمنــا اخلمــر وامليســر واألنصــاب‬\n  ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون) ‪.‬‬\n          ‫‪ -2‬املادة (‪ )2‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n          ‫‪ -3‬املادة (‪ )3‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n     ‫‪ -4‬املادة (‪ )1/56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n‫ادعــى املدعــى العــام علــى املدعــى عليهــم بتعاطــي الثالــث احلشــيش‬\n‫املخــدر ‪  ،‬والثانــي بتعاطــي احلبــوب احملظــورة ‪  ،‬واألول بتعاطــي احلبــوب‬\n‫احملظــورة ‪  ،‬واملســكر ‪  ،‬والســهر مــع إحــدى الفتيــات ‪  ،‬حيــث مت‬\n‫إيقافهــم مــن قبــل املباحــث العامــة إثــر األحداث التي وقعــت يف منطقتهم‬\n‫‪ ،‬وتبــن عــدم مشــاركتهم فيهــا ولكنهــم أقــروا مبــا جــاء يف دعــوى‬\n‫املدعــي العــام ‪ ،‬طلــب املدعــي العــام إقامــة حــد املســكر علــى املدعــى‬\n‫عليــه األول وتعزيــر املدعــى عليــه الثالــث حيــال مــا اســند إليــه وطلــب‬\n\n                                                                                  ‫‪118‬‬\n\f      ‫املدعــي العــام ســجن املدعــى عليهــم ومنعهــم مــن الســفر بنــاء علــى املــواد‬\n      ‫(  ‪ ) 56/ 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬أقــر‬\n      ‫املدعــى عليهــم مبــا نســب إليهــم بنــاء علــى مــا تقــدم حكمــت احملكمــة‬\n      ‫بحــد املســكر علــى املدعــى عليهمــا األول والثالــث‪ ،‬احلكــم علــى‬\n      ‫املدعــى عليــه األول والثانــي بالتعزيــر باجللــد لقــاء مــا نســب إليهــم و أبــدى‬\n      ‫املدعــى العــام اعتراضــه علــى احلكــم بــدون الئحــة‪ ،‬فيمــا قنــع املدعــى‬\n      ‫عليهــم مبــا صــدر بحقهــم مــن حكــم‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                              ‫االســتئناف‪.‬‬\n\n\n\n\n        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n        ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n        ‫برقــم ‪ ...‬وتاريــخ ‪ 1434 / 5 / 6‬ه ـ املقيــدة باحملكمــة برقــم ‪ ....‬وتاريــخ‬\n        ‫‪ 1434 / 5 / 6‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ‪ ... /‬ضــد ‪،....-1 /‬‬\n        ‫ســعودي اجلنســية حســب بطاقــة الهويــة الوطنيــة رقــم (‪، ...-2 .)....‬‬\n      ‫ســعودي اجلنســية حســب بطاقــة الهويــة الوطنيــة رقــم (‪  ، ...-3 . )....‬‬\n      ‫ســعودي اجلنســية حســب بطاقــة الهويــة الوطنيــة رقــم (‪ )....‬ففــي يــوم  ‬\n      ‫الســبت ‪1434/ 5 / 25‬هـ فتحت اجللســة الســاعة ‪  11 : 00‬وفيها حضر  ‬\n        ‫املدعــي العــام واملدعــى عليهــم املدونــة هوياتهــم بعاليــه وقــدم املدعــي‬\n        ‫العــام الئحــة الدعــوى املتضمنــة مــا يلــي ‪( :‬بصفتــي مدعي ـ ًا عامــا يف‬\n      ‫دائــرة التحقيــق واالدعــاء العــام مبحافظــة القطيــف أدعــي علــى كل‬\n      ‫مــن‪ ، ....-1 :‬البالــغ مــن العمــر (‪ )25‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ ، )....‬غيــر محصــن ‪ ،‬موظــف اهلــي ‪ ،‬أوقــف‬\n\n‫‪119‬‬\n\f  ‫بتاريــخ ‪1434/2/4‬ه ـ وأفــرج عنه بتاريخ ‪1434/2/10‬هـ اســتناد ًا للمادة‬\n  ‫(‪ )120‬مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬ويقيــم مبحافظــة القطيــف‪...-2.‬‬\n  ‫‪ ،‬البالــغ مــن العمــر (‪ )28‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل‬\n  ‫املدنــي رقــم (‪ ، )...‬غيــر محصــن ‪ ،‬عاطــل عــن العمــل ‪ ،‬أوقــف بتاريــخ‬\n  ‫‪1434/3/14‬ه ـ وأحيــل إلــى ســجن محافظــة القطيــف اســتناد ًا إلــى‬\n  ‫القــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬هــ‪ ، ....-3 .‬البالــغ‬\n  ‫مــن العمــر (‪ )30‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n  ‫رقــم (‪ ، )....‬محصــن ‪ ،‬موظــف أهلــي ‪ ،‬أوقــف بتاريــخ ‪1434/3/11‬ه ـ‬\n  ‫وأفــرج عنــه بتاريــخ ‪1434/3/18‬ه ـ اســتناد ًا للمــادة (‪ )120‬مــن نظــام‬\n  ‫اإلجــراءات اجلزائيــة ‪ ،‬ويقيــم مبحافظــة القطيــف‪ .‬حيــث انــه بتاريــخ‬\n  ‫‪1433/10/22‬ه ـ مت القبــض علــى املدعــى عليهــم اثــر األحــداث  التــي‬\n  ‫وقعــت مبحافظــة القطيــف وقــد اتضــح للمباحــث العامــة أن املذكوريــن‬\n  ‫لــم يرتكبــوا أي فعــل ضمــن النطــاق املنصــوص عليــه واملنــاط للمباحــث‬\n  ‫العامــة وأنهــم اقــروا بتعاطيهــم للمــواد املخــدرة‪ .‬وبســماع أقوالهــم اقــر‬\n  ‫(‪ ) ....‬بتعاطيــه للحشــيش املخــدر كمــا اقــر (‪ )...‬بتعاطيــه للحبــوب‬\n  ‫املنبهــة واحملظــورة واقــر (‪ )...‬بالســهر مــع  الفتيــات يف أحــد فنــادق‬\n  ‫البحريــن وشــربه املســكر‪ .‬وقــد أســفر التحقيــق معهــم إلــى توجيــه‬\n  ‫االتهــام للثالــث (‪ )...‬بتعاطــي احلشــيش املخــدر  والثانــي  (‪ )...‬بتعاطــي‬\n  ‫احلبــوب احملظــورة  وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة‬\n  ‫املخــدرات واتهــام األول (‪ )...‬بتعاطــي احلبــوب املنبهــة واحملظــورة وفق ـ ًا‬\n  ‫للفقــرة (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة املخــدرات والســهر‬\n‫مــع الفتيــات بأحــد فنــادق ‪ ....‬وشــربه للمســكر ‪  ،‬وذلــك العترافهــم  ‬\n  ‫بتعاطــي مــا نــوه عنــه املــدون علــى اللفــات رقــم (‪ )12‬والصفحــة رقــم (‪)2‬‬\n\n\n                                                                                     ‫‪120‬‬\n\f      ‫مــن ملــف التحقيــق املرفــق علــى اللفــة رقــم (‪ .)22‬وبالبحــث عمــا إذا‬\n      ‫كان لهــم ســوابق عثــر للثانــي علــى ســابقة حيــازة واســتعمال مخــدرات‬\n      ‫ولــم يعثــر لــأول والثالــث علــى ســوابق جنائيــة مســجلة‪ .‬وحيــث إن مــا‬\n      ‫أقــدم عليــه املذكــورون ‪ -‬وهــم بكامــل أهليتهــم املعتبــرة شــرعا ‪-‬فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب إثبــات مــا أســند إليهــم‬\n      ‫واحلكــم عليهــم مبــا يلــي‪ :‬أوال‪ :‬احلكــم علــى املدعــى عليــه ‪ ...‬بحــد‬\n      ‫الســكر لقــاء شــربه املســكر‪ .‬ثانيـاً‪ :‬إثبــات مــا اســند إلــى املدعــى عليــه‬\n      ‫‪ ...‬مــن الســهر مــع الفتيــات واحلكــم عليــه بعقوبــة تعزيريــه تزجــره وتــردع‬\n      ‫غيــره‪ .‬ثالثــا‪ :‬احلكــم عليهــم مبــا يلي‪-1:‬بعقوبــة الســجن الــواردة بالفقــرة‬\n      ‫رقــم (‪ )1‬مــن املــادة رقــم (‪ )41‬مــن نظــام املخدرات‪-2.‬منعهــم مــن الســفر‬\n      ‫وفقـ ًا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن نظــام املخــدرات‪ .‬وبــاهلل‬\n      ‫التوفيــق) ا‪ .‬ه ـ وبعــرض الدعــوى علــى املدعــى عليهــم أجــاب كل واحــد‬\n      ‫منهــم بقولــه مــا جــاء يف الدعــوى كلــه صحيــح هــذا جوابــي فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليهــم مبــا نســب إليهــم‬\n      ‫ممــا يســتوجب معاقبتهــم ولقولــه تعالــى ‪(  :‬يــا أيهــا الذيــن آمنــوا إمنــا‬\n      ‫اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه‬\n                                                                      ‫لعلكــم تفلحــون )‬\n      ‫وبنــاء علــى املــواد ‪ 3/2‬و‪ 56/1‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة فقــد حكمــت مبــا يلــي ‪-1 :‬ثبــوت إدانــة املدعــى عليــه األول‬\n      ‫( ‪ )...‬بتعاطــي احلبــوب املنبهــة واحملظــورة والســهر مــع الفتيــات بأحــد‬\n      ‫فنــادق ‪ ...‬وشــربه للمســكر ‪ ،‬وإدانــة املدعــى عليــه الثانــي (‪ )...‬بتعاطــي‬\n      ‫احلبــوب احملظــورة ‪ ،‬وإدانــة املدعــى عليــه الثالــث (‪ )...‬بتعاطــي احلشــيش‬\n      ‫املخــدر ‪ -2‬جلــد كل واحــد مــن املدعــى عليهمــا األول والثالــث ثمانــن‬\n\n\n‫‪121‬‬\n\f‫جلــدة حــد املســكر أمــام مــأ مــن النــاس ‪-3‬تعزيــر املدعــى عليــه الثانــي‬\n‫(‪ )...‬للتعاطــي بجلــده ســتني جلــدة دفعــة واحــدة ‪-4 .‬تعزيــر املدعــى عليــه‬\n‫األول ( ‪ )....‬للســهر مــع الفتيــات بجلــده خمســن جلــدة دفعــة واحــدة ‪،‬‬\n‫كمــا أفهمــت املدعــى عليهــم بانطبــاق املــادة ‪ 1/56‬مــن نظــام مكافحــة‬\n‫املخــدرات عليهــم والتــي تتضمــن املنــع مــن الســفر مــدة ســنتني وبعــرض‬\n‫احلكــم علــى الطرفــن قــرر املدعــي العــام عــدم قناعتــه ورغبتــه رفــع‬\n‫احلكــم حملكمــة االســتئناف بــدون الئحــة اعتراضيــة وقــرر املدعــى‬\n‫عليهــم قناعتهــم وبــاهلل التوفيــق وقــد مت االنتهــاء مــن حتريــره يف متــام‬\n                                                          ‫الســاعة ( ‪. )12 : 00‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم  الثالثــاء ‪1434/ 6 / 20‬هــ  فتحــت‬\n‫اجللســة الســاعة ‪  8 : 45‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب‬\n‫الفضيلــة قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم ‪ ...‬يف‬\n‫‪1434/6/11‬ه ـ املتضمــن املصادقــة علــى احلكــم  وبــاهلل التوفيــق وقــد‬\n                         ‫مت االنتهــاء مــن حتريــره يف متــام الســاعة ‪.  9 : 00‬‬\n\n\n\n\n                                                                                    ‫‪122‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":118,"source_page_end":122,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6bb45f98ac49ffb1037aa35e938d41b936ad73791d07285b0476789aed9d6f65","normalized_text_hash":"780cbd88372bad09350e3649c36d611397223d09a7aaf2b9e9617ad34fe7344e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p118-34221686"},{"id":"221af3d2-8c66-52fb-9a61-6692b847816a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي مخدرات -تعاطي الهيروين املخدر -إقرار -حد املسكر -التعزير باملنع من السفر .","document_number":"34211429","case_number":"34212234","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/12","year":"1434","subject":"مخدرات -تعاطي مخدرات -تعاطي الهيروين املخدر -إقرار -حد املسكر -التعزير باملنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪  34211429 :‬تاريخه ‪1434/5/12:‬هـ  ‬\n                           ‫رقم الدعوى‪34212234 :‬‬\n             ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫تاريخه‪1434/5/12:‬هـ‬         ‫‪34283662‬‬\n\n\n\n      ‫مخــدرات ‪ -‬تعاطــي مخــدرات ‪ -‬تعاطــي الهيرويــن املخــدر ‪ -‬إقــرار ‪ -‬حــد‬\n                                             ‫املســكر ‪ -‬التعزيــر باملنــع مــن الســفر ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قولــه تعالــى (يــا أيهــا الذيــن آمنــو إمنــا اخلمــر وامليســر واألنصــاب‬\n          ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون) ‪.‬‬\n                          ‫‪ -2‬قوله صلى اهلل عليه وسلم (كل مسكر حرام ) ‪.‬‬\n             ‫‪ -3‬املادة (‪)1/56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بتعاطــي الهيرويــن‪ ،‬حيــث مت‬\n      ‫القبــض علــى املدعــى عليــه إثــر االشــتباه بــه يف قضيــة ســرقة ‪ ،‬واعتــرف‬\n      ‫بتعاطيــه الهيرويــن املخــدر يف الســابق‪ ،‬وطلــب املدعــي العــام ســجن‬\n      ‫املدعــى عليــه ومنعــه مــن الســفر بنــاء علــى املــواد (‪ )56/41‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬أقــر املدعــى عليــه مبــا نســب‬\n      ‫إليــه‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بإقامــة حــد املســكر‬\n      ‫واملنــع مــن الســفر خــارج اململكــة   ملــدة ســنتني‪ ،‬وردت احملكمــة‬\n      ‫طلــب املدعــي العــام تعزيــر املدعــى عليــه وفق ـ ًا للمــادة (‪ )41‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة ؛ لعــدم انطباقــه بحقــه ‪،‬لعــدم‬\n\n‫‪123‬‬\n\f‫وجــود مخــدرات محــازة ‪ ،‬وقــرر املدعــى العــام طلبــه لالســتئناف بــدون‬\n‫الئحــة ‪  ،‬وقنــع املدعــى عليــه باحلكــم ‪ ،‬وصــدق احلكــم يف محكمــة‬\n                                                               ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــدهلل وحــده وبعــد ويف يــوم األحــد ‪1434/5/12‬ه ـ لــدي أنــا ‪....‬‬\n‫القاضــي باحملكمــة اجلزائيــة مبحافظــة القطيــف افتتحــت اجللســة يف‬\n‫الســاعة العاشــرة صباح ـ ًا بنــاء ًا علــى املعاملــة احملالــة لنــا مــن رئيــس‬\n‫هــذه احملكمــة برقــم ‪ ...‬يف ‪1434/5/7‬ه ـ واملقيــدة لــدى احملكمــة‬\n‫بالقيــد رقــم ‪ ....‬يف ‪1434/5/7‬ه ـ ويف هــذه اجللســة حضــر املدعــي العــام‬\n‫ا بصفتــي مدعي ـ ًا عامــا يف دائــرة اإلدعــاء العــام مبحافظــة‬      ‫وقــرر قائ ـ ً‬\n‫القطيــف أدعــي علــى ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ )....‬باالطــاع علــى محضــر القبــض املعــد مــن قبــل الدوريــات األمنيــة‬\n‫بســيهات بتاريــخ ‪1434/3/14‬ه ـ املتضمــن ورود بــاغ عــن شــخصني (مت‬\n‫فــرز أوراق مســتقلة مــن قبــل مكافحــة املخــدرات للمدعــو ‪- ...‬جــاري‬\n‫البحــث عنــه مــن قبــل مكافحــة املخــدرات‪ )-‬قامــا بســرقة اســطوانة‬\n‫غــاز تابعــة حملــات الغــاز وعنــد تفتيــش مركبتهمــا عثــر علــى عــدد أربــع‬\n‫اســطوانات غــاز غيــر تابعــة لهمــا فتــم القبــض عليهمــا (وجــرى فــرز هــذه‬\n‫األوراق للمتهمــن مــن قبــل دائــرة التحقيــق واإلدعــاء العــام بالقطيــف‬\n‫ملعاجلــة تهمــة تعاطيهمــا املــواد املخــدرة) وباالطــاع علــى محضــر اإلثبــات‬\n‫والفــرز املعــد مــن قبــل دائــرة التحقيــق واإلدعــاء العــام بالقطيــف بتاريــخ‬\n‫‪1434/3/17‬ه ـ املتضمــن أنــه جــرى فــرز هــذه األوراق للمدعــى عليــه‬\n‫بشــأن تعاطيــه الهرويــن وبقيــت القضيــة األساســية لديهــم الســتكمال‬\n\n                                                                                        ‫‪124‬‬\n\f      ‫إجراءاتهــا وباالطــاع علــى خطــاب دائــرة التحقيــق واإلدعــاء العــام‬\n      ‫بالقطيــف رقــم (‪ )2085‬وتاريــخ ‪1434/3/24‬ه ـ املوجــة ملكافحــة‬\n      ‫املخــدرات بالدمــام املتضمــن أنــه مت القبــض علــى املدعــى عليــه يف قضية‬\n      ‫ســرقة وحيــث اعتــرف املدعــى عليــه بتعاطيــه الهرويــن املخــدر لــذا جــرى‬\n      ‫بعــث هــذه األوراق املفــرزة اخلاصــة للمدعــى عليــه ملكافحــة املخــدرات‬\n      ‫إلكمــال الــازم بشــأن تعاطيــه الهرويــن املخــدر وقــد أســفر التحقيــق‬\n      ‫معــه إلــى توجيــه االتهــام لــه بتعاطــي الهرويــن املخــدر وفق ـ ًا للفقــرة (‪)2‬‬\n      ‫مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات وبالبحــث عمــا إذا كان‬\n      ‫لــه ســوابق عثــر لــه علــى خمــس ســوابق األولى شــرب مســكرات والثانية‬\n      ‫حيــازة واســتعمال املخــدرات والثالثــة حيــازة واســتعمال املخــدرات‬\n      ‫والرابعــة شــرب املســكرات واخلامســة محاولــة ســرقة وحيــث إن مــا‬\n      ‫أقــدم عليــه املذكور‪-‬وهــو  بكامــل أهليتــه  املعتبــرة شــرعا‪-‬فعل مجــرم‬\n      ‫ومعاقــب عليــه  شــرع ًا ونظامــا لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n      ‫عليــه مبــا يلي‪-1:‬بعقوبــة الســجن الــواردة بالفقــرة (‪ )1‬مــن املــادة رقــم‬\n      ‫(‪ )41‬مــن النظــام املشــار إليــه ‪-2‬منعــه مــن الســفر وفقـ ًا للفقــرة رقــم (‪)1‬‬\n      ‫مــن املــادة رقــم(‪ )56‬مــن النظــام املشــار إليــه هــذه دعــواي وبــاهلل التوفيــق‬\n      ‫هــذا وقــد حضــر يف اجللســة ‪ ...‬ســعودي مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ...‬هــذا وبســؤاله عمــا ذكــره املدعــي العــام يف دعــواه أجــاب بقولــه مــا‬\n      ‫ذكــره املدعــي العــام يف دعــواه  صحيــح كلــه فقــد قبــض علــي بتاريــخ‬\n      ‫‪1434/3/14‬ه ـ بســبب املشــاركة يف قضيــة ســرقة وقــد اعترفــت أننــي‬\n      ‫أســتعمل هرويــن وآخــر مــره اســتخدمته قبــل تســعة أشــهر علم ـ ًا بأننــي‬\n      ‫أســتخدمه منــذ قرابــة ســت ســنوات هــذا جوابــي فبنــاء ًا علــى مــا تقــدم‬\n      ‫مــن الدعــوى واإلجابــة ومــا قــرره الطرفــان وحيــث أقــر املدعــى عليــه‬\n\n\n‫‪125‬‬\n\f‫بدعــوى املدعــي العــام واســتعماله للهرويــن املخــدر وهــذا فعــل محــرم‬\n‫ومعاقــب عليــه شــرع ًا واســتناد ًا لقولــه تعالــى ((يــا أيهــا الــذي آمنــوا إمنــا‬\n‫اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه‬\n‫لعلكــم تفلحــون )) وحلديــث ((كل مســكر حــرام)) ومبــا أن املدعــى‬\n‫عليــه لــم يكــن معــه مــواد مخــدرة محــازة جلميــع ذلــك فقــد حكمــت‬\n‫مبــا يلــي أو ًال ‪ :‬جلــد املدعــى عليــه ثمانــن جلــدة دفعــة واحــدة حــد‬\n‫املســكر ثاني ـ ًا ‪ :‬رد دعــوى املدعــي العــام يف طلبــه إثبــات تطبيــق املــادة‬\n‫احلاديــة واألربعــن لعــدم وجــود مــواد مخــدرة محــازة مــع املدعــى عليــه‬\n‫وبإعــان احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة باحلكــم‬\n‫أمــا املدعــي العــام فقــرر عــدم القناعــة وطالــب بالتمييــز ورفــع احلكــم‬\n‫إلــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة فأجبتــه لذلــك كمــا‬\n‫أفهمــت املدعــى عليــه مبــا ورد يف الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪)56‬‬\n‫حســب طلــب املدعــي العــام وأمــرت بإخــراج قــرار بذلــك ثــم رفــع احلكــم‬\n‫إلــى محكمــة االســتئناف وصلــى اهلل وســلم علــى نبينــا محمــد وحــرر يف‬\n                                                                       ‫‪1434/5/12‬ه ـ ‪.‬‬\n‫احلمــدهلل وحــده وبعــد ويف يــوم الســبت ‪1434/7/8‬ه ـ افتتحــت اجللســة‬\n‫يف الســاعة احلاديــة عشــرة والنصــف هــذا وقــد وردتنــا املعاملــة مــن‬\n‫رئيــس محكمــة االســتئناف باملنطقــة الشــرقية باخلطــاب رقــم ‪ ....‬تاريــخ‬\n‫‪1434/6/13‬ه ـ وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة‬\n‫رقــم ‪ ...‬يف ‪1434/6/10‬ه ـ واملتضمــن مالحظــة أصحــاب الفضيلــة مبــا‬\n‫نصــه ( وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن‬\n‫فضيلتــه لــم يحكــم مبنــع املدعــى عليــه مــن الســفر حيــث ثبــت لــدى‬\n‫فضيلتــه اســتعمال املدعــى عليــه للهرويــن وطالــب بذلــك املدعــي العــام‬\n\n\n                                                                                            ‫‪126‬‬\n\f        ‫ملالحظــة مــا ذكــر) ا‪.‬ه ـ وأجيــب أصحــاب الفضيلــة وفقنــي اهلل وإياهــم‬\n        ‫للصــواب بأنــه مت اإلشــارة واإلفهــام لذلــك يف آخــر القــرار لــذا أمــرت‬\n        ‫بإحلــاق ذلــك يف القــرار ثــم إعــادة املعاملــة إلــى محكمــة االســتئناف‬\n                               ‫حســب التعليمــات وللبيــان حــرر يف ‪1434/7/8‬ه ـ ‪.‬‬\n        ‫احلمــدهلل وحــده وبعــد ويف يــوم األثنــن ‪1434/8/22‬ه ـ افتتحــت اجللســة‬\n        ‫يف الســاعة الثامنــة والنصــف صباح ـ ًا هــذا وقــد وردتنــا املعاملــة مــن‬\n      ‫رئيــس محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب اخلطــاب رقــم  ‬\n        ‫وتاريــخ ‪1434/8/17‬ه ـ وقــد ظهــر علــى القــرار مبــا نصــه ( احلمــدهلل‬\n        ‫وحــده وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا القرار رقــم وتاريــخ ‪1434/5/12‬هـ‬\n        ‫الصــادر مــن فضيلــة القاضــي الشــيخ ‪ ....‬وأصدرنــا القــرار رقــم وتاريــخ‬\n        ‫‪1434/7/30‬ه ـ املتضمــن املصادقــة علــى احلكــم قاضــي اســتئناف‬\n        ‫‪ ...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n        ‫‪...‬ختمــه وتوقيعــه )وللبيــان حــرر يف ‪1434/8/22‬ه ـ واهلل املوفــق وصلــى‬\n                                                      ‫اهلل وســلم علــى نبينــا محمــد ‪.‬‬\n\n\n\n\n‫‪127‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":123,"source_page_end":127,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8178247d44e408c09a6cd3d86b9339f738bbdc646b322aabff34cf06052a8798","normalized_text_hash":"8556b5fad0369fac972bfdf34748dd754da83ccce8915b65e8374cb17493863a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p123-34211429"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

